#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-20

# Security Tests: JSON-island HTML breakout in playgrounds (#3019)
#
# Playgrounds embed their state in an HTML JSON island:
#   <script type="application/json" id="lpp-state">{ ... }</script>
#
# The `type="application/json"` attribute is IRRELEVANT to the HTML tokenizer.
# Any `</script` sequence inside that block terminates the element at PARSE time,
# before JSON.parse and before any renderer-side sanitizer (esc / stCls / riskColor
# / safeUrl) has a chance to run. The remainder of the state is then parsed as live
# markup. JSON.stringify does NOT escape `<`, so a writer emitting a plan title of
#   "My plan</script><img src=x onerror=...>"
# ships a working XSS that no JavaScript-level guard can reach and that CodeQL's
# js/xss-through-dom does not model (it is an HTML-parser issue, not a JS dataflow).
#
# INVARIANT: inside a JSON island, `<` MUST be written as the < escape.
# That is valid JSON, round-trips to `<` through JSON.parse, and is inert to the
# HTML tokenizer.
#
# Priority: HIGH
# Reference: OWASP A03 (Injection) / DOM XSS via markup breakout

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'; NC=$'\033[0m'
PASS=0; FAIL=0
log_pass() { echo "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }
section() { echo; echo "${YELLOW}$1${NC}"; }

echo "=========================================="
echo "  JSON-Island Breakout Tests (#3019)"
echo "=========================================="

# ---------------------------------------------------------------------------
section "1. No shipped playground contains a raw breakout sequence"
# ---------------------------------------------------------------------------
# Scan every HTML file that declares a JSON island and check that each island
# survives the HTML tokenizer intact.
#
# THE DETECTOR THIS REPLACES DID NOT WORK. It captured the island body with a
# non-greedy `(.*?)</script\s*>` and then searched that body for `</script`. The
# non-greedy match ENDS at the first `</script>` — which, for the attack in this
# file's own header, is the injected breakout itself. The captured body was
# therefore always the truncated prefix (`{"t":"x`) and never contained the
# sequence being searched for. Measured: a planted
# `{"t":"x</script><img src=x onerror=alert(1)>"}` island scanned CLEAN. The
# section only ever caught malformed variants like `</script foo`, never the
# real thing.
#
# What it does now mirrors the actual vulnerability. Per the HTML spec, script
# data ends at the first `</script` followed by whitespace, `/`, or `>`, whatever
# the type= attribute says. So: cut the island at that first terminator and hand
# the result to a JSON parser. A clean island's JSON is complete at that point; a
# broken-out island's JSON is truncated mid-token and fails to parse. Verified
# against all 11 real islands in the tree — zero false positives — and it turns
# the planted attack RED.
#
# If a future template holds a non-JSON placeholder inside an island, this fires.
# That is the correct answer, not a bug: keep the placeholder JSON-shaped.
#
# The scanner also reports how many islands it matched. A clean scan over ZERO
# islands is not evidence of anything — if the island markup were renamed or the
# playgrounds moved out of the walked tree, this section would report green
# forever while guarding nothing. Measured at authoring time: 11 islands across
# 926 HTML files, so the count assertion below is live, not decorative.
SCAN=$(python3 - "$PROJECT_ROOT" <<'PY'
import json, os, re, subprocess, sys

root = sys.argv[1]
OPEN_RE = re.compile(r'<script[^>]*type=["\']application/json["\'][^>]*>', re.I)
END_RE = re.compile(r'</script[\s/>]', re.I)

# Other checkouts of this repo must not be walked, or their copies of these same
# HTML files are counted and reported twice (#3410). Pruning by DIRECTORY NAME
# was the bug: it removed `.worktrees` but not `.claude/worktrees`, whose leaf is
# named `worktrees` — and that is the layout CC creates natively, the default
# since #3315. Derive the roots from git so a third layout cannot repeat it, and
# keep both literals as a backstop for UNregistered debris that git will not list.
def other_checkouts(repo):
    roots = set()
    try:
        out = subprocess.run(
            ["git", "-C", repo, "worktree", "list", "--porcelain"],
            capture_output=True, text=True, timeout=10,
        ).stdout
        paths = [l.split(" ", 1)[1].strip() for l in out.splitlines() if l.startswith("worktree ")]
        # Skip the tree BEING SCANNED, not paths[0]: `git worktree list` puts the
        # MAIN worktree first, which is a different tree whenever this test runs
        # from inside a worktree. Pruning by paths[1:] made the scanned tree its
        # own prune root, and the anti-vacuity assertion below caught it.
        me = os.path.realpath(repo)
        for pth in paths:
            real = os.path.realpath(pth)
            # Skip the tree being scanned, AND any checkout that CONTAINS it.
            # The mandated layout nests worktrees inside the repo
            # (<repo>/.worktrees/<task>), so the main checkout is an ANCESTOR of
            # this one — prefix-matching against it would prune the entire scan
            # and report a vacuous clean. Only disjoint or nested-below roots
            # are genuinely "another checkout" from here.
            if real != me and not me.startswith(real + os.sep):
                roots.add(real)
    except (OSError, subprocess.SubprocessError, IndexError):
        pass                          # silent: best-effort — literals below carry it
    for literal in (".worktrees", os.path.join(".claude", "worktrees")):
        lit = os.path.realpath(os.path.join(repo, literal))
        me_real = os.path.realpath(repo)
        if lit != me_real and not me_real.startswith(lit + os.sep):
            roots.add(lit)
    return roots

PRUNE_ROOTS = other_checkouts(root)

def inside_other_checkout(path):
    real = os.path.realpath(path)
    return any(real == r or real.startswith(r + os.sep) for r in PRUNE_ROOTS)

bad = []
islands = 0
for base, dirs, files in os.walk(root):
    dirs[:] = [
        d for d in dirs
        if d not in {".git", "node_modules"}
        and not inside_other_checkout(os.path.join(base, d))
    ]
    for name in files:
        if not name.endswith(".html"):
            continue
        p = os.path.join(base, name)
        try:
            text = open(p, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        for m in OPEN_RE.finditer(text):
            islands += 1
            rest = text[m.end():]
            end = END_RE.search(rest)
            if end is None:
                bad.append((os.path.relpath(p, root), "island is never terminated"))
                continue
            body = rest[: end.start()]
            try:
                json.loads(body)
            except ValueError as exc:
                bad.append((
                    os.path.relpath(p, root),
                    "island truncated at the tokenizer's first </script (%s)" % exc,
                ))
print("ISLANDS %d" % islands)
for path, why in sorted(set(bad)):
    print("BAD %s :: %s" % (path, why))
PY
)
ISLANDS=$(printf '%s\n' "$SCAN" | awk '$1 == "ISLANDS" { print $2 }')
VIOLATIONS=$(printf '%s\n' "$SCAN" | awk '$1 == "BAD" { sub(/^BAD /, ""); print }')

if [ "${ISLANDS:-0}" -eq 0 ]; then
  log_fail "scanner matched NO JSON islands — the scan below is vacuous, not clean"
elif [ -z "$VIOLATIONS" ]; then
  log_pass "no JSON island contains a raw </script sequence (${ISLANDS} islands scanned)"
else
  log_fail "JSON island breakout present in:"
  echo "$VIOLATIONS" | sed 's/^/      /'
fi

# ---------------------------------------------------------------------------
section "2. The breakout is real (proves the test guards something)"
# ---------------------------------------------------------------------------
# A guard nobody can trigger is theatre. Build the hostile document and confirm a
# real HTML tokenizer lifts an executable element out of the island.
if python3 - <<'PY'
import json, sys
from html.parser import HTMLParser

payload = json.dumps({"title": 'plan</script><img src=x onerror="alert(1)">'})
page = f'<script type="application/json" id="s">{payload}</script>'

class T(HTMLParser):
    escaped = False
    def handle_starttag(self, tag, attrs):
        if tag == "img" and any(k == "onerror" for k, _ in attrs):
            T.escaped = True

T().feed(page)
sys.exit(0 if T.escaped else 1)
PY
then
  log_pass "unescaped island demonstrably yields a live <img onerror> element"
else
  log_fail "could not reproduce the breakout — test may no longer guard anything"
fi

# ---------------------------------------------------------------------------
section "3. The \\u003c escape neutralises it and round-trips"
# ---------------------------------------------------------------------------
if python3 - <<'PY'
import json, sys
from html.parser import HTMLParser

original = 'plan</script><img src=x onerror="alert(1)">'
escaped = json.dumps({"title": original}).replace("<", "\\u003c")

class T(HTMLParser):
    escaped_out = False
    def handle_starttag(self, tag, attrs):
        if tag == "img":
            T.escaped_out = True

T().feed(f'<script type="application/json" id="s">{escaped}</script>')
round_trips = json.loads(escaped)["title"] == original
sys.exit(0 if (not T.escaped_out and round_trips) else 1)
PY
then
  log_pass "\\u003c blocks the breakout AND JSON.parse still yields the original '<'"
else
  log_fail "\\u003c escape did not behave as required"
fi

# ---------------------------------------------------------------------------
section "4. The invariant is documented where writers will see it"
# ---------------------------------------------------------------------------
TEMPLATE="$PROJECT_ROOT/src/skills/shared/assets/playground-exemplars/living-plan.template.html"
STANDARD="$PROJECT_ROOT/src/skills/shared/rules/playground-visual-standard.md"
if [ -f "$TEMPLATE" ] && grep -q 'u003c' "$TEMPLATE"; then
  log_pass "exemplar template states the \\u003c invariant"
else
  log_fail "exemplar template does not document the \\u003c invariant"
fi
if [ -f "$STANDARD" ] && grep -q 'u003c' "$STANDARD"; then
  log_pass "playground visual standard states the \\u003c invariant"
else
  log_fail "playground visual standard does not document the \\u003c invariant"
fi

echo
echo "=========================================="
echo "  Passed: ${GREEN}${PASS}${NC}  Failed: ${RED}${FAIL}${NC}"
echo "=========================================="
[ "$FAIL" -eq 0 ]
